-- Madrasa foundation schema (M0).
-- Rules (CLAUDE.md): UUID v7 primary keys generated by the app; school_id on every
-- school-owned row; sync columns (created_at, updated_at, updated_by, deleted_at, hlc) on
-- every mutable table; soft deletes; JSONB custom fields on core entities; append-only audit log.

CREATE TABLE schools (
    id                          UUID PRIMARY KEY,
    name                        TEXT NOT NULL,
    code                        TEXT NOT NULL,
    city                        TEXT NOT NULL DEFAULT '',
    is_demo                     BOOLEAN NOT NULL DEFAULT FALSE,
    academic_year_start_month   SMALLINT NOT NULL DEFAULT 4 CHECK (academic_year_start_month IN (4, 8)),
    currency                    TEXT NOT NULL DEFAULT 'PKR',
    custom                      JSONB NOT NULL DEFAULT '{}'::jsonb,
    created_at                  TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at                  TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_by                  UUID,
    deleted_at                  TIMESTAMPTZ,
    hlc                         TEXT NOT NULL
);
CREATE UNIQUE INDEX schools_code_uq ON schools (upper(code)) WHERE deleted_at IS NULL;

CREATE TABLE users (
    id                  UUID PRIMARY KEY,
    school_id           UUID NOT NULL REFERENCES schools (id),
    username            TEXT NOT NULL,
    full_name           TEXT NOT NULL,
    email               TEXT,
    password_hash       TEXT NOT NULL,
    is_active           BOOLEAN NOT NULL DEFAULT TRUE,
    failed_login_count  INTEGER NOT NULL DEFAULT 0,
    locked_until        TIMESTAMPTZ,
    last_login_at       TIMESTAMPTZ,
    custom              JSONB NOT NULL DEFAULT '{}'::jsonb,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_by          UUID,
    deleted_at          TIMESTAMPTZ,
    hlc                 TEXT NOT NULL
);
CREATE UNIQUE INDEX users_username_uq ON users (school_id, lower(username)) WHERE deleted_at IS NULL;
CREATE INDEX users_school_idx ON users (school_id);

CREATE TABLE roles (
    id          UUID PRIMARY KEY,
    school_id   UUID NOT NULL REFERENCES schools (id),
    code        TEXT NOT NULL,
    name        TEXT NOT NULL,
    is_system   BOOLEAN NOT NULL DEFAULT FALSE,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_by  UUID,
    deleted_at  TIMESTAMPTZ,
    hlc         TEXT NOT NULL,
    UNIQUE (school_id, code)
);

-- One row per grant: role X may do permission code Y.
CREATE TABLE permissions (
    id          UUID PRIMARY KEY,
    school_id   UUID NOT NULL REFERENCES schools (id),
    role_id     UUID NOT NULL REFERENCES roles (id),
    code        TEXT NOT NULL,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_by  UUID,
    deleted_at  TIMESTAMPTZ,
    hlc         TEXT NOT NULL,
    UNIQUE (role_id, code)
);
CREATE INDEX permissions_role_idx ON permissions (role_id);

CREATE TABLE user_roles (
    id          UUID PRIMARY KEY,
    school_id   UUID NOT NULL REFERENCES schools (id),
    user_id     UUID NOT NULL REFERENCES users (id),
    role_id     UUID NOT NULL REFERENCES roles (id),
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_by  UUID,
    deleted_at  TIMESTAMPTZ,
    hlc         TEXT NOT NULL,
    UNIQUE (user_id, role_id)
);
CREATE INDEX user_roles_user_idx ON user_roles (user_id);

-- Session tokens. Only the SHA-256 hash of the token is stored.
CREATE TABLE sessions (
    id              UUID PRIMARY KEY,
    school_id       UUID NOT NULL REFERENCES schools (id),
    user_id         UUID NOT NULL REFERENCES users (id),
    token_hash      TEXT NOT NULL UNIQUE,
    expires_at      TIMESTAMPTZ NOT NULL,
    last_seen_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    revoked_at      TIMESTAMPTZ,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_by      UUID,
    deleted_at      TIMESTAMPTZ,
    hlc             TEXT NOT NULL
);
CREATE INDEX sessions_user_idx ON sessions (user_id);

-- Key/value settings. school_id NULL = instance-wide (e.g. edition, node id).
CREATE TABLE settings (
    id          UUID PRIMARY KEY,
    school_id   UUID REFERENCES schools (id),
    key         TEXT NOT NULL,
    value       JSONB NOT NULL,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_by  UUID,
    deleted_at  TIMESTAMPTZ,
    hlc         TEXT NOT NULL,
    UNIQUE NULLS NOT DISTINCT (school_id, key)
);

-- Append-only audit log: who, what, when, old value, new value.
CREATE TABLE audit_log (
    id              UUID PRIMARY KEY,
    school_id       UUID REFERENCES schools (id),
    actor_user_id   UUID REFERENCES users (id),
    action          TEXT NOT NULL CHECK (action IN ('create', 'update', 'delete', 'login', 'login_failed', 'lockout', 'logout')),
    entity          TEXT NOT NULL,
    entity_id       UUID,
    old_value       JSONB,
    new_value       JSONB,
    at              TIMESTAMPTZ NOT NULL DEFAULT now(),
    hlc             TEXT NOT NULL
);
CREATE INDEX audit_log_entity_idx ON audit_log (entity, entity_id);
CREATE INDEX audit_log_school_at_idx ON audit_log (school_id, at DESC);

CREATE FUNCTION audit_log_immutable() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    RAISE EXCEPTION 'audit_log is append-only';
END;
$$;
CREATE TRIGGER audit_log_no_update BEFORE UPDATE ON audit_log
    FOR EACH ROW EXECUTE FUNCTION audit_log_immutable();
CREATE TRIGGER audit_log_no_delete BEFORE DELETE ON audit_log
    FOR EACH ROW EXECUTE FUNCTION audit_log_immutable();
CREATE TRIGGER audit_log_no_truncate BEFORE TRUNCATE ON audit_log
    FOR EACH STATEMENT EXECUTE FUNCTION audit_log_immutable();

-- Registry of custom fields allowed in each entity's `custom` JSONB column.
CREATE TABLE custom_field_definitions (
    id          UUID PRIMARY KEY,
    school_id   UUID NOT NULL REFERENCES schools (id),
    entity      TEXT NOT NULL,
    key         TEXT NOT NULL,
    label       TEXT NOT NULL,
    field_type  TEXT NOT NULL CHECK (field_type IN ('text', 'number', 'date', 'boolean', 'select')),
    required    BOOLEAN NOT NULL DEFAULT FALSE,
    options     JSONB NOT NULL DEFAULT '[]'::jsonb,
    position    INTEGER NOT NULL DEFAULT 0,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_by  UUID,
    deleted_at  TIMESTAMPTZ,
    hlc         TEXT NOT NULL,
    UNIQUE (school_id, entity, key)
);
